"""Doré Design P1 — click-motion lab for Living Water 8:5 currents."""

PAGE_ID='motion-p1-living-current'

def _page():
    return {'id':PAGE_ID,'name':'Motion · P1 Click Dynamics','canvas':{'w':1440,'h':960},'nodes':[],'design_experiment':{'schema':'dore.design-experiment.v1','track':'motion-language','prototype':'P1','status':'prototype','source':'user-direction-2026-09-09','principles':['no-light-effects','click-is-primary-motion','8:5-source-continuity','A-shared-element-focus','B-weight-reflow','C-preview-to-destination','D-codrops-grid-to-full-preview','tap-not-hover','reduced-motion'],'references':['Motion shared layout / FLIP','GSAP Flip reflow','View Transitions shared element','Codrops Grid To Full Preview / Gwen Bogaert / MIT'],'acceptance':['all-three-clickable','codrops-original-live-reference','selected-tile-remains-identifiable','no-modal-pop','no-continuous-fx','reversible','mobile-tap']}}

def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        for p in w.get('pages',[]):
            if p.get('id')==PAGE_ID:
                p.update(_page());return base.save(w)
        w['pages'].append(_page());return base.save(w)
    base.workspace=workspace

def install_editor(html):
    html=html.replace("'multiwrite-cover'])","'multiwrite-cover','motion-p1-living-current'])")
    return html.replace('DORÉ DESIGN 1.9 · PROMOTION PIPELINE','DORÉ DESIGN 2.0 · DESIGN LAB')

def render_p1(edit=False):
    badge='<div class="badge">DORÉ DESIGN · MOTION LAB · P1</div>' if edit else ''
    return '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>P1 Click Dynamics</title><style>
*{box-sizing:border-box}html,body{margin:0;background:#181713;color:#eee8d9;font-family:"Cormorant Garamond","Noto Serif TC",serif}.badge{position:fixed;z-index:99;top:10px;left:10px;background:#171714;border:1px solid #6f6748;padding:7px 9px;font:9px ui-monospace,monospace}.intro{padding:48px 5vw 24px;border-bottom:1px solid #494431}.ey{font:10px ui-monospace,monospace;letter-spacing:.16em;color:#cebd74}.intro h1{font-size:clamp(38px,5vw,72px);font-weight:400;margin:.15em 0}.intro p{max-width:850px;color:#bcb4a3;line-height:1.5}.lab{display:grid;gap:30px;padding:30px 3vw 70px}.exp{border:1px solid #4a4533;background:#201f1a;overflow:hidden}.head{display:flex;gap:16px;align-items:baseline;padding:12px 14px;border-bottom:1px solid #403b2d}.id{color:#cebd74;font:11px ui-monospace,monospace}.head h2{font-size:22px;font-weight:400;margin:0}.note{margin-left:auto;color:#8e8778;font:10px ui-monospace,monospace}.stage{position:relative;height:560px;overflow:hidden;background:#11110f}.river{position:absolute;inset:0;display:grid;align-content:center;gap:14px;padding:24px;transition:filter .55s,opacity .55s}.row{display:flex;gap:12px;align-items:center;transition:transform .7s cubic-bezier(.2,.75,.2,1)}.row:nth-child(even){transform:translateX(-6%)}.tile{appearance:none;border:1px solid #726a4c;background:linear-gradient(135deg,#353126,#1c1b17);color:#f1ead9;height:108px;width:173px;flex:0 0 auto;text-align:left;padding:14px;cursor:pointer;position:relative;overflow:hidden;transition:width .7s cubic-bezier(.2,.75,.2,1),height .7s cubic-bezier(.2,.75,.2,1),transform .7s cubic-bezier(.2,.75,.2,1),opacity .45s,border-color .45s}.tile.w2{width:358px}.tile small{display:block;color:#cebd74;font:8px ui-monospace,monospace;letter-spacing:.12em}.tile strong{display:block;font-size:22px;font-weight:400;margin-top:7px}.tile:focus-visible{outline:2px solid #cebd74;outline-offset:2px}.focus{position:absolute;z-index:8;left:7%;right:7%;top:9%;bottom:9%;border:1px solid #a3935c;background:linear-gradient(135deg,#3a3528,#171713);padding:clamp(24px,5vw,64px);opacity:0;transform:scale(.84);pointer-events:none;transition:opacity .55s,transform .7s cubic-bezier(.2,.75,.2,1)}.focus.on{opacity:1;transform:scale(1);pointer-events:auto}.focus small{color:#cebd74;font:9px ui-monospace,monospace;letter-spacing:.14em}.focus h3{font-size:clamp(38px,6vw,78px);font-weight:400;margin:.15em 0}.focus p{max-width:620px;color:#c8c0af;font-size:18px;line-height:1.5}.close,.enter{border:1px solid #827752;background:#191813;color:#eee5d0;padding:10px 14px;cursor:pointer}.enter{background:#cebd74;color:#171714}.exp.focused .river{filter:brightness(.45);opacity:.55}.exp.reflow .tile.selected{width:544px;height:170px;border-color:#cebd74;transform:translateY(-10px)}.exp.reflow .tile:not(.selected){opacity:.56}.preview{position:absolute;z-index:9;inset:auto 4% 4%;min-height:40%;background:#242119;border:1px solid #8d8057;padding:26px;transform:translateY(120%);transition:transform .75s cubic-bezier(.2,.75,.2,1)}.preview.on{transform:translateY(0)}.preview h3{font-size:42px;font-weight:400;margin:.1em 0}.preview .actions{display:flex;gap:10px;margin-top:22px}.destination{position:absolute;z-index:12;inset:0;background:#eee8da;color:#1b1a16;padding:10%;clip-path:inset(100% 0 0 0);transition:clip-path .8s cubic-bezier(.2,.75,.2,1)}.destination.on{clip-path:inset(0)}.destination h3{font-size:clamp(48px,7vw,92px);font-weight:400;margin:.1em 0}.destination button{border:1px solid #2d2a21;background:transparent;padding:10px 14px;cursor:pointer}.codrops-stage{height:min(78vh,760px);min-height:620px;background:#eee;position:relative}.codrops-stage iframe{width:100%;height:100%;border:0;display:block}.sourcebar{display:flex;gap:14px;align-items:center;padding:10px 14px;border-top:1px solid #403b2d;color:#a49b88;font:10px ui-monospace,monospace}.sourcebar a{color:#cebd74;text-decoration:none}.sourcebar strong{color:#eee8d9;font-weight:400}@media(max-width:700px){.stage{height:520px}.tile{width:132px;height:92px}.tile.w2{width:276px}.exp.reflow .tile.selected{width:310px}.note{display:none}.focus{left:4%;right:4%}.codrops-stage{min-height:520px}}@media(prefers-reduced-motion:reduce){*{transition-duration:.01ms!important}}
</style></head><body>'''+badge+'''<header class="intro"><div class="ey">MOTION LAB · P1 · CLICK, NOT LIGHT</div><h1>8:5 Click Dynamics</h1><p>前三組是 Living Water 內容流實驗；D 直接放入 Codrops / Gwen Bogaert 的成熟 Grid to Full Preview 原作，先看它真正的 puzzle / clip-path 動態，不仿寫。</p></header><main class="lab">'''+_experiment('a','A','Shared Element Focus','原位取得焦點；其他內容退讓。')+_experiment('b','B','Weight Reflow','點擊後內容權重從 1 變 2/3，整條流重新讓位。')+_experiment('c','C','Preview → Destination','先從內容流長出 preview，再連續進入正文。')+'''<section class="exp" data-mode="d"><div class="head"><span class="id">D</span><h2>Codrops · Grid To Full Preview</h2><span class="note">GSAP + clip-path · original live demo</span></div><div class="codrops-stage"><iframe src="https://tympanus.net/Tutorials/GridToFullPreview/" title="Codrops Grid To Full Preview by Gwen Bogaert"></iframe></div><div class="sourcebar"><strong>成熟原作直接運行</strong><span>桌面端把鼠標移入 grid 卡片觀看拼圖式合攏與 full preview。</span><a href="https://tympanus.net/Tutorials/GridToFullPreview/" target="_blank" rel="noreferrer">Demo ↗</a><a href="https://github.com/gwen-bo/codrops-grid-to-preview" target="_blank" rel="noreferrer">MIT source ↗</a></div></section></main><script>
(function(){
 document.querySelectorAll('.exp[data-mode="a"],.exp[data-mode="b"],.exp[data-mode="c"]').forEach(function(exp){
  var focus=exp.querySelector('.focus'),preview=exp.querySelector('.preview'),dest=exp.querySelector('.destination');
  exp.querySelectorAll('.tile').forEach(function(tile){tile.addEventListener('click',function(){var title=tile.querySelector('strong').textContent,kind=tile.querySelector('small').textContent;exp.querySelectorAll('.tile').forEach(function(x){x.classList.remove('selected')});tile.classList.add('selected');if(exp.dataset.mode==='a'){focus.querySelector('small').textContent=kind;focus.querySelector('h3').textContent=title;exp.classList.add('focused');focus.classList.add('on')}if(exp.dataset.mode==='b'){exp.classList.add('reflow')}if(exp.dataset.mode==='c'){preview.querySelector('small').textContent=kind;preview.querySelector('h3').textContent=title;preview.classList.add('on')}})});
  exp.querySelectorAll('[data-close]').forEach(function(b){b.addEventListener('click',function(){exp.classList.remove('focused','reflow');focus.classList.remove('on');preview.classList.remove('on');dest.classList.remove('on');exp.querySelectorAll('.tile').forEach(function(x){x.classList.remove('selected')})})});var enter=exp.querySelector('[data-enter]');if(enter)enter.addEventListener('click',function(){dest.querySelector('h3').textContent=preview.querySelector('h3').textContent;dest.classList.add('on')});
 });
})();</script></body></html>'''

def _experiment(mode,letter,title,note):
    def cards(items): return ''.join('<button type="button" class="tile%s"><small>%s</small><strong>%s</strong></button>'%((' w2' if w==2 else ''),k,t) for k,t,w in items)
    rows='<div class="row">'+cards([('JOURNAL','守望',2),('PRAYER','儆醒',1),('ONE','查經',1),('FEATURE','一座光明的城',2)])+'</div><div class="row">'+cards([('STORY','看見',1),('WITNESS','見證人',2),('HYMN','頌讚',1),('CHURCH','Living Water',1)])+'</div>'
    return '<section class="exp" data-mode="%s"><div class="head"><span class="id">%s</span><h2>%s</h2><span class="note">%s</span></div><div class="stage"><div class="river">%s</div><div class="focus"><small>JOURNAL</small><h3>守望</h3><p>被選中的 8:5 從原有內容流取得視覺重量；內容身份保持連續，而不是突然彈出另一個 modal。</p><button type="button" class="close" data-close>返回內容流</button></div><div class="preview"><small>JOURNAL</small><h3>守望</h3><p>這是閱讀前的 editorial preview。下一步才進真正正文。</p><div class="actions"><button type="button" class="close" data-close>收回</button><button type="button" class="enter" data-enter>進入正文</button></div></div><div class="destination"><small>JOURNAL</small><h3>守望</h3><p>正文頁。正式版將把原圖與標題作 shared-element continuity，而不是硬切頁。</p><button type="button" data-close>返回</button></div></div></section>'%(mode,letter,title,note,rows)
